/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_priceType">priceType</param>
/// <param name = "_custPriceGroupId">custPriceGroupId</param>
/// <param name = "_smmBusRelGroupId">smmBusRelGroup</param>
/// <param name = "_itemId">itemId</param>
/// <param name = "_priceDate">priceDate</param>
/// <param name = "_currency">currency</param>
/// <returns>priceDiscTable</returns>
public static PriceDiscTable        findPriceDisc(PriceType            _priceType,
                                                   PriceGroupId        _custPriceGroupId,
                                                   PriceGroupId        _smmBusRelGroupId,
                                                   ItemId              _itemId,
                                                   TransDate           _priceDate,
                                                   CurrencyCode        _currency)
{
    PriceDiscTable                  priceDiscTable;
    AVAPriceDiscGroupSearch         priceDiscGroupSearch = new AVAPriceDiscGroupSearch();
    switch (_priceType)
    {
        case  PriceType::PriceSales :
            priceDiscTable  = priceDiscGroupSearch.searchPrice(_custPriceGroupId,_itemId,_priceDate,_currency);
            break;
        case PriceType::LineDiscSales :
            priceDiscTable= priceDiscGroupSearch.searchDisc(_custPriceGroupId,_smmBusRelGroupId,_itemId,_priceDate);
            break;
        default: 
            break;

    }

    return priceDiscTable;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_custPriceGroupId">custPriceGroupId</param>
/// <param name = "_smmBusRelGroupId">smmBusRelGroup</param>
/// <param name = "_itemId">itemId</param>
/// <param name = "_priceDate">priceDate</param>
/// <returns>priceDiscTable</returns>
protected  PriceDiscTable searchDisc(PriceGroupId        _custPriceGroupId,
                                       PriceGroupId        _smmBusRelGroupId,
                                       ItemId              _itemId,
                                       TransDate           _priceDate)
{
    PriceGroupId                            priceDiscGroup;
    //PriceDiscPartyCodeType                  accountCode = PriceDiscPartyCodeType::GroupId;
    PriceDiscTable                          priceDiscTable;
    PriceDiscProductCodeTypeOrderedList     priceDiscProductCodeTypeOrderedList = PriceDiscProductCodeTypeOrderedList::newFromOrder(SortOrder::Ascending);
    List                                    priceDiscGroupList = this.createPriceGroupList(_custPriceGroupId,_smmBusRelGroupId);

    PriceDiscProductCodeType    itemCode;
    ItemRelation                itemRelation;


    ListEnumerator  priceDiscGroupListEnumerator                   = priceDiscGroupList.getEnumerator();
    ListEnumerator  priceDiscProductCodeTypeEnumerator   = priceDiscProductCodeTypeOrderedList.getEnumerator();
    boolean         continueSearch = true;

    while (priceDiscProductCodeTypeEnumerator.moveNext() && continueSearch)
    {
        itemCode  = priceDiscProductCodeTypeEnumerator.current();
        itemRelation =  this.getLineDiscItemRelation(itemCode,_itemId);
        priceDiscGroupListEnumerator.reset();
        while (priceDiscGroupListEnumerator.moveNext  () && continueSearch)
        {
            priceDiscGroup = priceDiscGroupListEnumerator.current();

            select firstonly priceDiscTable
                where priceDiscTable.ItemCode == itemCode
                   && priceDiscTable.ItemRelation == itemRelation
                   && ((priceDiscTable.AccountCode  == PriceDiscPartyCodeType::GroupId
                   && priceDiscTable.AccountRelation == priceDiscGroup
                   && priceDiscGroup != '')    ||
                      (priceDiscTable.AccountCode == PriceDiscPartyCodeType ::All
                   && priceDiscGroup == ''))
                   && (priceDiscTable.Module       == ModuleInventCustVend::Cust     || priceDiscTable.Module       == ModuleInventCustVend::Invent)
                   && priceDiscTable.FromDate <= _priceDate
                   && (priceDiscTable.ToDate >= _priceDate || priceDiscTable.ToDate == dateNull())
                   && priceDiscTable.relation == PriceType::LineDiscSales;

            if (priceDiscTable.RecId)
            {
                continueSearch = false;
            }
        }

    }

    return priceDiscTable;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_accountCode">_accountCode</param>
/// <param name = "_accountRelation">_accountRelation</param>
/// <param name = "_itemCode">_itemCode</param>
/// <param name = "_itemRelation">_itemRelation</param>
/// <param name = "_priceDate">_priceDate</param>
/// <param name = "_relation">_relation</param>
/// <returns>PriceDiscTable</returns>
public static PriceDiscTable searchDiscCodeRelation(PriceDiscPartyCodeType        _accountCode,
                                          PriceDiscAccountRelation      _accountRelation,
                                          PriceDiscProductCodeType      _itemCode,
                                          PriceDiscItemRelation         _itemRelation,
                                          TransDate                     _priceDate,
                                          PriceType                     _relation)
{
    PriceDiscTable                          priceDiscTable;
    select firstonly priceDiscTable
        where priceDiscTable.ItemCode           == _itemCode
            && priceDiscTable.ItemRelation      == _itemRelation
            && priceDiscTable.AccountCode       == _accountCode
            && priceDiscTable.AccountRelation   == _accountRelation
            && (priceDiscTable.Module       == ModuleInventCustVend::Cust     || priceDiscTable.Module       == ModuleInventCustVend::Invent)
            && priceDiscTable.FromDate <= _priceDate
            && (priceDiscTable.ToDate >= _priceDate || priceDiscTable.ToDate == dateNull())
            && priceDiscTable.relation == _relation;

    return priceDiscTable;
}

/// <summary>
/// designed FromAVA
/// </summary>
/// <param name = "_custPriceGroupId">custPriceGroupId</param>
/// <param name = "_itemId">itemId</param>
/// <param name = "_priceDate">priceDate</param>
/// <param name = "_currencyCode">currencyCode</param>
/// <returns>priceDiscTable</returns>
protected  PriceDiscTable searchPrice(    PriceGroupId        _custPriceGroupId,
                                            ItemId              _itemId,
                                            TransDate           _priceDate,
                                            CurrencyCode        _currencyCode)
{
    PriceGroupId                            priceDiscGroup;
    PriceDiscPartyCodeType                  accountCode = PriceDiscPartyCodeType::GroupId;
    PriceDiscTable                          priceDiscTable;

    PriceDiscProductCodeType                itemCode = PriceDiscProductCodeType::Table;
    ItemRelation                            itemRelation = _itemId;
    CurrencyCode                            currency = _currencyCode;
    CurrencyCode                            genericCurrency; 

    priceDiscGroup = _custPriceGroupId;

    boolean         continueSearch = true;


    select firstonly priceDiscTable
        where priceDiscTable.ItemCode == itemCode
            && priceDiscTable.ItemRelation == itemRelation
            && priceDiscTable.AccountCode  == accountCode
            && priceDiscTable.AccountRelation == priceDiscGroup
            && priceDiscTable.Module       == ModuleInventCustVend::Cust 
            && priceDiscTable.Currency        == currency    
            && priceDiscTable.FromDate <= _priceDate
            && (priceDiscTable.ToDate >= _priceDate || priceDiscTable.ToDate == dateNull())
            && priceDiscTable.relation == PriceType::PriceSales;

    if (priceDiscTable.RecId)
    {
        continueSearch = false;
    }

    if (continueSearch)
    {
        genericCurrency =  SalesParameters::find().GenericCurrency;
        if (currency != genericCurrency)
        {
            currency = genericCurrency;
            select firstonly priceDiscTable
            where priceDiscTable.ItemCode == itemCode
                && priceDiscTable.ItemRelation == itemRelation
                && priceDiscTable.AccountCode  == accountCode
                && priceDiscTable.AccountRelation == priceDiscGroup
                && priceDiscTable.Currency        == currency
                && priceDiscTable.Module       == ModuleInventCustVend::Cust
                && priceDiscTable.FromDate <= _priceDate
                && (priceDiscTable.ToDate >= _priceDate || priceDiscTable.ToDate == dateNull())
                && priceDiscTable.relation == PriceType::PriceSales;
        }

    }


    return priceDiscTable;
}

protected ItemRelation getLineDiscItemRelation(PriceDiscProductCodeType _itemCode, ItemId       _itemId)
{
    switch (_itemCode)
    {
        case PriceDiscProductCodeType::Table:
            return _itemId;
        case PriceDiscProductCodeType::GroupId : 
            return InventTableModule::find(_itemId,ModuleInventPurchSales::Sales).LineDisc;
        case PriceDiscProductCodeType::All :
            return '';
    }
    return '';
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_custPriceGroupId">custPriceGroupId</param>
/// <param name = "_smmBusRelGroupId">smmBusRelGroupId</param>
/// <returns>List</returns>
protected List createPriceGroupList(PriceGroupId    _custPriceGroupId, PriceGroupId _smmBusRelGroupId)
{
    List            priceGroupList = new List(Types::String);
    priceGroupList.addEnd(_custPriceGroupId);
    priceGroupList.addEnd(_smmBusRelGroupId);
    priceGroupList.addEnd('');

    return priceGroupList;
}
